echo '=== apt lists 更新时间 ==='; stat -c '%y %n' /var/lib/apt/lists 2>/dev/null; ls -lt --time-style=long-iso /var/lib/apt/lists 2>/dev/null | head -n 5; echo; echo '=== 内核相关可升级包(apt 缓存) ==='; apt list --upgradable 2>/dev/null | grep -i linux; echo; echo '=== 当前内核版本 ==='; uname -r; echo; echo '=== 最新可用内核镜像包 ==='; apt-cache policy linux-image-generic linux-image-virtual 2>/dev/null | head -n 20; echo; echo '=== ubuntu-security-status ==='; (ubuntu-security-status 2>/dev/null || pro security-status 2>/dev/null || echo '未安装 ubuntu-advantage-tools') | head -n 25
